export interface ConnectorConfig {
  /** Slack Bot Token with chat:write scope */
  slackBotToken: string
  /** Twilio Auth Token (used as password for Basic auth) */
  twilioAuthToken: string
  /** Twilio Account SID (used as username for Basic auth and in URL) */
  twilioAccountSid: string
  /** Twilio phone number to send replies from (E.164 format) */
  twilioFromNumber: string
  /** Optional injected fetch for testing */
  fetch?: typeof fetch
}

export interface TwilioWebhookPayload {
  Body: string
  From: string
  ChannelName?: string
}

export interface HandleResult {
  slackMessageTs: string
  slackChannelId: string
  twilioMessageSid: string
}

const SALES_REGEX = /pricing|quote|demo/i

function validatePayload(payload: TwilioWebhookPayload): void {
  if (!payload.Body || typeof payload.Body !== 'string') {
    throw new Error('Missing required field: Body')
  }
  if (!payload.From || typeof payload.From !== 'string') {
    throw new Error('Missing required field: From')
  }
}

function determineSlackChannel(body: string): string {
  return SALES_REGEX.test(body) ? '#sales' : '#support'
}

async function postToSlack(
  config: ConnectorConfig,
  channel: string,
  text: string
): Promise<{ ok: boolean; channel: string; ts: string }> {
  const fetchFn = config.fetch ?? fetch
  const response = await fetchFn('https://slack.com/api/chat.postMessage', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({ channel, text })
  })

  if (!response.ok) {
    throw new Error(`Slack API error: ${response.status} ${response.statusText} at POST https://slack.com/api/chat.postMessage`)
  }

  return response.json() as Promise<{ ok: boolean; channel: string; ts: string }>
}

async function sendTwilioReply(
  config: ConnectorConfig,
  to: string,
  body: string
): Promise<{ sid: string }> {
  const fetchFn = config.fetch ?? fetch
  const url = `https://api.twilio.com/2010-04-01/Accounts/${config.twilioAccountSid}/Messages.json`
  const auth = btoa(`${config.twilioAccountSid}:${config.twilioAuthToken}`)

  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      'Authorization': `Basic ${auth}`,
      'Content-Type': 'application/x-www-form-urlencoded'
    },
    body: new URLSearchParams({ To: to, From: config.twilioFromNumber, Body: body }).toString()
  })

  if (!response.ok) {
    throw new Error(`Twilio API error: ${response.status} ${response.statusText} at POST ${url}`)
  }

  return response.json() as Promise<{ sid: string }>
}

export async function handle(
  payload: TwilioWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  validatePayload(payload)

  const slackChannel = determineSlackChannel(payload.Body)
  const slackResult = await postToSlack(config, slackChannel, payload.Body)

  const replyBody = 'Thanks for your message!'
  const twilioResult = await sendTwilioReply(config, payload.From, replyBody)

  return {
    slackMessageTs: slackResult.ts,
    slackChannelId: slackResult.channel,
    twilioMessageSid: twilioResult.sid
  }
}

function btoa(str: string): string {
  if (typeof btoa === 'function' && typeof globalThis !== 'undefined' && 'btoa' in globalThis) {
    return (globalThis as any).btoa(str)
  }
  return Buffer.from(str, 'binary').toString('base64')
}

